            aOrbiterF = (((aWandererC + RotL64(aScatter, 28U)) + RotL64(aCarry, 51U)) + 0x92FC849395C7E9FDULL) + aTwistOrbiterAssignSaltC[((aIndex + 164U)) & S_SALT1];
            aOrbiterH = ((aWandererK + RotL64(aCross, 13U)) + RotL64(aCarry, 37U)) + 0x60C0E91F469F38F1ULL;
            aOrbiterK = ((aWandererE + RotL64(aPrevious, 21U)) + RotL64(aCarry, 19U)) + 0x4098BB0312C59AA7ULL;
            aOrbiterI = (aWandererB + RotL64(aIngress, 51U)) + 0xB1C9A4D6962AEF45ULL;
            aOrbiterG = (aWandererF + RotL64(aCross, 41U)) + 0x36A1C26DF0627E18ULL;
            aOrbiterA = (aWandererI + RotL64(aPrevious, 57U)) + 0x0C8CD46E22109D4FULL;
            //
            aOrbiterD = ((aOrbiterD + aOrbiterF) + 0x577B8D05A6625323ULL) + aTwistOrbiterUpdateSaltC[(((255U - aIndex) + 152U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterD) ^ 0xCB2CB76AC991CD33ULL;
