            //
            aOrbiterK = ((aOrbiterK + aOrbiterG) + 0x9C87BE3DB30A8C33ULL) + aTwistOrbiterUpdateSaltB[((aIndex + 171U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterK) ^ 0x236399922CD38E69ULL;
