            aOrbiterA = (aOrbiterA + aOrbiterI) + 0x67A32FC056978929ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterA) ^ 0xB8548E6682342B1FULL;
            aOrbiterD = RotL64((aOrbiterD * 0xF02756BB345FAF53ULL), 3U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterK) + 0x0DED1EB0A5BC518FULL) + aTwistOrbiterUpdateSaltA[((aIndex + 244U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterH) ^ 0x30793E1A077048AFULL;
