            //
            aOrbiterG = (aOrbiterG + aOrbiterA) + 0x6B28B5B6672953EFULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterG) ^ 0x194E7D26A998CB81ULL) ^ aTwistOrbiterUpdateSaltE[((aIndex + 16U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x355DCE7AC430EC0DULL), 41U);
            //
            aIngress = RotL64(aOrbiterI, 57U) ^ aOrbiterD;
