            //
            aWandererI = aWandererI ^ ((RotL64(aIngress, 57U) + RotL64(aOrbiterG, 29U)) + aOrbiterK);
            aWandererH = aWandererH + ((((RotL64(aCross, 5U) + aOrbiterD) + RotL64(aOrbiterI, 41U)) + RotL64(aCarry, 21U)) + aTwistWandererUpdateSaltE[((aIndex + 46U)) & S_SALT1]);
            aWandererB = aWandererB ^ ((RotL64(aScatter, 19U) + RotL64(aOrbiterA, 11U)) + aOrbiterD);
            aWandererE = aWandererE + (((RotL64(aPrevious, 43U) + aOrbiterF) + RotL64(aOrbiterH, 5U)) + RotL64(aCarry, 41U));
            aWandererK = aWandererK ^ ((RotL64(aCross, 13U) + RotL64(aOrbiterK, 54U)) + aOrbiterH);
            aWandererC = aWandererC + (((RotL64(aPrevious, 28U) + aOrbiterA) + RotL64(aOrbiterI, 35U)) + aTwistWandererUpdateSaltA[((aIndex + 226U)) & S_SALT1]);
            aWandererF = aWandererF ^ ((RotL64(aIngress, 51U) + RotL64(aOrbiterF, 19U)) + aOrbiterD);
