            aOrbiterE = (aWandererH + RotL64(aPrevious, 51U)) + 0x51686F8159D1D8D5ULL;
            aOrbiterC = ((aWandererI + RotL64(aIngress, 13U)) + 0x051E2852C1ECEDEBULL) + aTwistOrbiterAssignSaltD[(((255U - aIndex) + 165U)) & S_SALT1];
            //
            aOrbiterA = (aOrbiterA + aOrbiterB) + 0x19BE931FC6B2E87EULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterA) ^ 0x64EFB77818DDAB76ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x49EE8CB674ABDD7FULL), 43U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterI) + 0x54A8924FB7278F5BULL) + aTwistOrbiterUpdateSaltA[((aIndex + 192U)) & S_SALT1];
