            //
            aOrbiterA = (aWandererA + RotL64(aPrevious, 19U)) + 0x4834C54211DCC984ULL;
            aOrbiterG = (aWandererF + RotL64(aCross, 35U)) + 0x93C15244ADD4E196ULL;
            aOrbiterK = (aWandererH + RotL64(aScatter, 58U)) + 0x7867971C908BE109ULL;
