            aWandererG = aWandererG ^ ((RotL64(aCross, 53U) + RotL64(aOrbiterA, 51U)) + aOrbiterI);
            aWandererH = aWandererH + (((RotL64(aPrevious, 34U) + aOrbiterB) + RotL64(aOrbiterJ, 11U)) + RotL64(aCarry, 29U));
