            aOrbiterB = ((aWandererC + RotL64(aIngress, 34U)) + RotL64(aCarry, 35U)) + 0xCEA485C6113E4561ULL;
            aOrbiterA = ((aWandererA + RotL64(aPrevious, 11U)) + 0xC8474E5CF3F3F5A4ULL) + aKeyRotateBOrbiterAssignSaltD[((aIndex + 176U)) & S_SALT1];
            aOrbiterE = (((aWandererG + RotL64(aCross, 57U)) + RotL64(aCarry, 43U)) + 0x197F42759CFAC1C9ULL) + aKeyRotateBOrbiterAssignSaltE[((aIndex + 227U)) & S_SALT1];
            aOrbiterD = (aWandererJ + RotL64(aScatter, 27U)) + 0x9CBA8A8D04D010A2ULL;
            aOrbiterG = (aWandererF + RotL64(aPrevious, 18U)) + 0x27824E2EED793296ULL;
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterK) + 0x074B67E375AFDB47ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterJ) ^ 0x18694F3CF080C2EDULL;
            aOrbiterH = RotL64((aOrbiterH * 0x1F6767B111379C49ULL), 23U);
